import type { TileType } from "~/engine";

/**
 * Shared props interface for TileInventory and MobileInventory.
 *
 * Both components render the same logical tile-selection UI
 * (desktop sidebar vs mobile horizontal bar) and share this contract.
 */
export interface InventoryProps {
  remaining: { straight: number; curve: number };
  selectedType: TileType | null;
  onSelect: (type: TileType | null) => void;
  disabled?: boolean;
  removeMode?: boolean;
  onToggleRemoveMode?: () => void;
}

/**
 * Computed state for a single tile-type button in the inventory.
 * Extracted so tile-selection logic lives in one place.
 */
export interface TileButtonState {
  isSelected: boolean;
  isEmpty: boolean;
  available: boolean;
  count: number;
}

/**
 * Derive the display/interaction state for one tile-type button.
 */
export function getTileButtonState(
  remaining: InventoryProps["remaining"],
  invKey: keyof InventoryProps["remaining"],
  selectedType: TileType | null,
  type: TileType,
  removeMode: boolean | undefined,
  disabled: boolean | undefined,
): TileButtonState {
  const count = remaining[invKey];
  const isSelected = selectedType === type && !removeMode;
  const isEmpty = count <= 0;
  const available = !disabled && !isEmpty;
  return { isSelected, isEmpty, available, count };
}

/**
 * Handle a tile-type button click. Returns the new selection value,
 * and indicates whether remove mode should be toggled off.
 */
export function handleTileButtonClick(
  state: TileButtonState,
  type: TileType,
  removeMode: boolean | undefined,
  onToggleRemoveMode: (() => void) | undefined,
  onSelect: (type: TileType | null) => void,
): void {
  if (!state.available) return;
  if (onToggleRemoveMode && removeMode) onToggleRemoveMode();
  onSelect(state.isSelected ? null : type);
}

import { TILE_TYPE_DEFS } from "~/engine";
import { TilePreview } from "./TilePreview";
import type { InventoryProps } from "./inventory-shared";
import { getTileButtonState, handleTileButtonClick } from "./inventory-shared";

export function TileInventory({
  remaining,
  selectedType,
  onSelect,
  disabled,
  removeMode,
  onToggleRemoveMode,
}: InventoryProps) {
  return (
    <div className="bg-white/90 backdrop-blur-sm rounded-r-2xl shadow-lg border border-l-0 border-gray-200 py-3 px-3 flex flex-col gap-2.5 -ml-3 mt-4">
      {/* Tile pieces */}
      {TILE_TYPE_DEFS.map(({ type, label, invKey }) => {
        const btn = getTileButtonState(remaining, invKey, selectedType, type, removeMode, disabled);

        return (
          <button
            key={type}
            onClick={() => handleTileButtonClick(btn, type, removeMode, onToggleRemoveMode, onSelect)}
            disabled={!btn.available}
            className={`
              relative flex flex-col items-center gap-1
              p-2 rounded-xl transition-all duration-150 select-none
              ${btn.isSelected
                ? "bg-teal-100 ring-2 ring-teal-500 shadow-md scale-105"
                : btn.isEmpty
                  ? "opacity-30 cursor-not-allowed"
                  : "hover:bg-teal-50 hover:scale-105 cursor-pointer"
              }
            `}
          >
            <TilePreview type={type} size={64} selected={btn.isSelected} />

            {/* Count display */}
            <span className={`text-lg font-bold tabular-nums ${
              btn.isSelected ? "text-teal-700" : "text-gray-500"
            }`}>
              {btn.count}
            </span>
          </button>
        );
      })}

      {/* Divider */}
      <div className="h-px bg-gray-200 mx-1" />

      {/* Remove tool */}
      <button
        onClick={() => {
          if (disabled) return;
          onSelect(null);
          onToggleRemoveMode?.();
        }}
        disabled={disabled}
        className={`
          flex flex-col items-center justify-center gap-1
          p-2 rounded-xl transition-all duration-150 select-none
          ${removeMode
            ? "bg-red-100 ring-2 ring-red-400 scale-105"
            : disabled
              ? "opacity-30 cursor-not-allowed"
              : "hover:bg-red-50 hover:scale-105 cursor-pointer"
          }
        `}
        title="Remove placed tiles"
      >
        <div className={`w-16 h-16 flex items-center justify-center rounded-lg ${
          removeMode ? "bg-red-50" : "bg-gray-50"
        }`}>
          <svg width="28" height="28" viewBox="0 0 22 22" fill="none">
            <path d="M6 6l10 10M16 6L6 16"
              stroke={removeMode ? "#ef4444" : "#9ca3af"}
              strokeWidth="2.5" strokeLinecap="round" />
          </svg>
        </div>
      </button>
    </div>
  );
}

import { TILE_TYPE_DEFS } from "~/engine";
