        className={`
          p-2 rounded-xl transition-all select-none
          ${removeMode
            ? "bg-red-100 ring-2 ring-red-400"
            : disabled
              ? "opacity-30 cursor-not-allowed"
              : "hover:bg-red-50 cursor-pointer"
