        title="Remove placed tiles"
      >
        <svg width="22" height="22" viewBox="0 0 22 22" fill="none">
          <path d="M6 6l10 10M16 6L6 16"
            stroke={removeMode ? "#ef4444" : "#9ca3af"}
            strokeWidth="2.5" strokeLinecap="round" />
        </svg>
      </button>
    </div>
  );
}

